cd /workspace && node -e "
const fs = require('fs');
const JSZip = require('jszip');

async function main() {
  const data = fs.readFileSync('/workspace/testbed/docs/travel_summary.docx');
  const zip = await JSZip.loadAsync(data);
  let docXml = await zip.file('word/document.xml').async('string');

  const oldText = 'Booking BK-B70889 | user_59b22691 |  →  | business | Status: confirmed | \$1180';
  const newText = 'Booking BK-B70889 | user_59b22691 | JFK → LHR | business | Status: On Time | \$1180';

  if (!docXml.includes(oldText)) {
    console.log('ERROR: Could not find target text');
    return;
  }

  docXml = docXml.replace(oldText, newText);

  zip.file('word/document.xml', docXml);
  const output = await zip.generateAsync({ type: 'nodebuffer' });
  fs.writeFileSync('/workspace/testbed/docs/travel_summary.docx', output);
  console.log('SUCCESS: Updated BK-B70889 route to JFK → LHR and status to On Time');
}
main();
"

